window.AUTH=window.AUTH||{};window.AUTH["22-7386"]={"d":"22-7386","id":"2023/22-7386","n":"McIntosh v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Louis McIntosh","date":"2023-11-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-7386/290619/20231127145352936_McIntosh%20Opening%20Brief%20-%20final.pdf","side":"pet","n":94},{"k":"respondent","label":"Brief of respondent United States","date":"2024-01-10","url":"https://www.supremecourt.gov/DocketPDF/22/22-7386/295413/20240110152445974_22-7386bsUnitedStates.pdf","side":"res","n":72},{"k":"reply","label":"Reply of petitioner Louis McIntosh","date":"2024-02-09","url":"https://www.supremecourt.gov/DocketPDF/22/22-7386/300266/20240209150608196_McIntosh%20Reply%20-%20FINAL%20to%20print.pdf","side":"pet","n":37}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r17_nmio.pdf","tr":true,"items":[{"t":"case","label":"Barnhart v. Peabody Coal Co.","cite":"537 U.S. 149","y":2003,"id":"2002/01-705","sc":1,"by":{"0":"38","1":"21, 37"},"q":[{"src":"brief","b":1,"text":"infer congressional intent to limit an agency’s power to get a mandatory job done merely from a specification to act by a certain time.","cite":"537 U.S. 149, 160"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"intent to limit an [offcial's] power to get a mandatory job done merely from a specifcation to act by a certain time,","cite":"537 U. S., at 160"}]},{"t":"case","label":"Beech Aircraft Corp. v. Rainey","cite":"488 U.S. 153","y":1988,"id":"1988/87-981","sc":1,"by":{"0":"18"}},{"t":"case","label":"Bittner v. United States","cite":"598 U.S. 85","y":2023,"id":"2022/21-1195","sc":1,"by":{"0":"44"}},{"t":"case","label":"Bostock v. Clayton Cnty.","cite":"140 S. Ct. 1731","y":2020,"id":"2019/17-1618","sc":1,"by":{"0":"21"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"by":{"0":"14, 44"},"q":[{"src":"brief","b":0,"text":"nor can a court extend that deadline for equitable reasons.","cite":"551 U.S. 205"}]},{"t":"case","label":"Brock v. Pierce Cnty.","cite":"476 U.S. 253","y":1986,"id":"1985/85-385","sc":1,"by":{"0":"38","1":"21, 27, 38","2":"8"}},{"t":"case","label":"City of Chicago v. Envtl. Defense Fund","cite":"511 U.S. 328","y":1994,"id":"1993/92-1639","sc":1,"by":{"0":"21"}},{"t":"case","label":"Dolan v. United States","cite":"560 U.S. 605","y":2010,"id":"2009/09-367","sc":1,"by":{"0":"2-3, 8-10, 13-16, 32, 34, 36-39, 41, 43-45","1":"10-12, 14, 18-20, 24, 33, 35-39, 41","2":"3, 8, 17"},"q":[{"src":"brief","b":0,"text":"permit[] or tak[e] the action to which the statute attached the deadline.","cite":"560 U.S. at 610"},{"src":"brief","b":0,"text":"have varied depending upon the particular statute and time limit at issue.","cite":"560 U.S. 605, 610"},{"src":"brief","b":1,"text":"Rule 32.2 ‘does not specify a consequence for noncompliance with its timing provisions.’","cite":"560 U.S. at 611"},{"src":"brief","b":1,"text":"‘does not specify a consequence for noncompliance with’ its ‘timing provisions.’","cite":"560 U.S. at 611"},{"src":"brief","b":2,"text":"seeks speed primarily to help the victims of crime and secondarily to help the defendant,","cite":"560 U.S. 605, 612"},{"src":"brief","b":2,"text":"criminal forfeiture is a mandatory consequence of conviction,","cite":"560 U.S. at 608"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"`not deprive a judge . . . of the power to take the action to which the deadline applies if the deadline is missed.'","cite":"560 U. S. 605, 611"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"regulate the timing of motions or claims brought before the court.","cite":"560 U. S., at 610"},{"src":"argument","who":"Mr. Yurowitz","text":"Those cases involved either administrative rules and the concern of imposing mandatory conditions on bureaucratic agencies or rules designed to protect third parties, not before the court, such as the victims in Dolan and the public in Montalvo-Murillo."},{"src":"argument","who":"Mr. Yurowitz","text":"So Dolan set -- set forth three potential rules for -- the -- to -- three potential buckets, a jurisdictional rule, a -- a -- a mandatory claim-processing rule, and a time-related directive."},{"src":"argument","who":"Mr. Guarnieri","text":"Rule 32.2(b)(2)(B) is not such a rule for all the reasons that this Court identified in Dolan with respect to the analogous timing requirement in the Mandatory Victims Restitution Act."}]},{"t":"case","label":"Eberhart v. United States","cite":"546 U.S. 12","y":2005,"id":"2005/04-9949","sc":1,"by":{"0":"33, 35, 44","1":"23, 42, 43","2":"7, 10"},"q":[{"src":"brief","b":0,"text":"instruct the court on the limits of its discretion to","cite":"546 U.S. 12"},{"src":"argument","who":"Mr. Yurowitz","text":"So this -- even -- in this Court in Eberhart, when it was construing Rule 33, it didn't look to a harmless error rule because it -- held that it was a mandatory claim-processing rule."},{"src":"argument","who":"Mr. Yurowitz","text":"Even this Court in Eberhart, when it was dealing with Rule 33, it has the same ability for a judge to extend the deadline. Defense counsel could make a motion saying probably it's -- I can't do it sufficiently in time, and the rule permits a court to extend it."},{"src":"argument","who":"Mr. Guarnieri","text":"And the key case there, I think, is Eberhart addressing Rule 33, which is the rule specifying the time limits for moving for a new trial after conviction."}]},{"t":"case","label":"Fort Bend Cnty. v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"by":{"0":"14, 36","2":"8, 10"},"q":[{"src":"brief","b":0,"text":"In recent years, the Court has undertaken to ward off profligate use of the term","cite":"139 S. Ct. 1843, 1848"}]},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"by":{"0":"34","1":"27","2":"8, 10"},"q":[{"src":"argument","who":"Mr. Yurowitz","text":"Gonzalez versus Thaler and Santos-Zacaria are both obligations that are placed on the court. A -- a -- a preliminary order -- it's an order."},{"src":"argument","who":"Justice Alito","text":"Can I go back to your -- your prior answer when you spoke about Santos-Zacaria and Gonzalez versus Thaler? In -- in the latter case, Gonzalez versus Thaler, the provision said a certificate of appealability may issue only if the applicant has made a substantial showing of the denial of a constitutional right."},{"src":"argument","who":"Mr. Yurowitz","text":"I -- I -- I don't, but, Justice Alito, even in those cases, the ultimate responsibility, for example, in Gonzalez, it was the court that had to issue the court -- the -- the -- the COA."}]},{"t":"case","label":"Gutierrez de Martinez v. Lamango","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"by":{"0":"19"}},{"t":"case","label":"Hamer v. Neighborhood Hous. Servs. of Chi.","cite":"583 U.S. 17","y":2017,"id":"2017/16-658","sc":1,"by":{"0":"33"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"by":{"0":"9, 15, 34, 35","1":"26","2":"8, 10"},"q":[{"src":"brief","b":0,"text":"seek to promote the orderly progress of litigation by requiring that the parties take certain procedural steps at certain specified times,","cite":"562 U.S. 428, 435"},{"src":"brief","b":1,"text":"requir[e] that the parties take certain procedural steps at certain specified times.","cite":"562 U.S. 428, 435"}]},{"t":"case","label":"Knick v. Twp. of Scott","cite":"139 S. Ct. 2162","y":2019,"id":"2018/17-647","sc":1,"by":{"0":"43"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"by":{"0":"15, 16, 33, 34","1":"23, 27, 42","2":"8, 10"},"q":[{"src":"brief","b":0,"text":"instruct the court on the limits of its discretion","cite":"540 U.S. at 456"},{"src":"brief","b":1,"text":"do not create or withdraw federal jurisdiction","cite":"540 U.S. 443, 453"}]},{"t":"case","label":"Lagos v. United States","cite":"138 S. Ct. 1684","y":2018,"id":"2017/16-1519","sc":1,"by":{"0":"38"}},{"t":"case","label":"Lexecon Inc. v. Milberg Weiss Bershad Hynes & Lerach","cite":"523 U.S. 26","y":1998,"id":"1997/96-1482","sc":1,"by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"creat[ing] an obligation impervious to judicial discretion.","cite":"523 U.S. 26, 35"}]},{"t":"case","label":"Libretti v. United States","cite":"516 U.S. 29","y":1995,"id":"1995/94-7427","sc":1,"by":{"0":"39","1":"3, 23, 36"},"q":[{"src":"brief","b":1,"text":"an aspect of punishment imposed following conviction of a substantive criminal offense.","cite":"516 U.S. 29, 39"},{"src":"brief","b":1,"text":"aspect of [the] punishment imposed following convic- tion of a substantive criminal offense.","cite":"516 U.S. 29, 39"}]},{"t":"case","label":"Manrique v. United States","cite":"581 U.S. 116","y":2017,"id":"2016/15-7250","sc":1,"by":{"0":"33, 44","1":"42"},"q":[{"src":"brief","b":1,"text":"[b]y definition, mandatory claim-processing rules * * * are not subject to harmless-error analysis.","cite":"581 U.S. 116, 125"}]},{"t":"case","label":"McIntosh v. United States","cite":"143 S. Ct. 399","y":2022,"url":"https://www.courtlistener.com/c/S.%20Ct./143/399/","sc":1,"by":{"0":"8"}},{"t":"case","label":"Paroline v. United States","cite":"572 U.S. 434","y":2014,"id":"2013/12-8561","sc":1,"by":{"0":"38"}},{"t":"case","label":"Santos-Zacaria v. Garland","cite":"598 U.S. 411","y":2023,"id":"2022/21-1436","sc":1,"by":{"0":"13, 14, 16, 34, 35","1":"26","2":"8, 10, 14"},"q":[{"src":"brief","b":0,"text":"the jury [to] be retained to determine the forfeitability of specific property","cite":"598 U.S. 411, 416"},{"src":"brief","b":0,"text":"govern how courts and litigants operate within th[e] bounds","cite":"598 U.S. at 416"},{"src":"argument","who":"Mr. Yurowitz","text":"Gonzalez versus Thaler and Santos-Zacaria are both obligations that are placed on the court. A -- a -- a preliminary order -- it's an order."},{"src":"argument","who":"Justice Alito","text":"Can I go back to your -- your prior answer when you spoke about Santos-Zacaria and Gonzalez versus Thaler? In -- in the latter case, Gonzalez versus Thaler, the provision said a certificate of appealability may issue only if the applicant has made a substantial showing of the denial of a constitutional right."},{"src":"argument","who":"Mr. Guarnieri","text":"I mean, there are rules, for example, the provision of the INA that was at issue in Santos-Zacaria, which my friend mentioned this morning, that are phrased in terms of action by the court but clearly are designed to impose on the parties an obligation to take some step, such as exhausting administrative remedies."}]},{"t":"case","label":"Scarborough v. Principi","cite":"541 U.S. 401","y":2004,"id":"2003/02-1657","sc":1,"by":{"0":"34","2":"8, 10"}},{"t":"case","label":"Sebelius v. Auburn Reg’l Med. Ctr.","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"by":{"0":"11, 34","2":"8, 10"}},{"t":"case","label":"Union Pac. R. Co. v. Bhd. of Locomotive Eng'rs","cite":"558 U.S. 67","id":"2009/08-604","sc":1,"by":{"0":"33"}},{"t":"case","label":"United States v. Jacobson","cite":"15 F.3d 19","y":1994,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/15/19/","by":{"0":"6"}},{"t":"case","label":"United States v. Liquidators of Eur. Fed. Credit Bank","cite":"630 F.3d 1139","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/630/1139/","by":{"0":"27"}},{"t":"case","label":"United States v. Maddux","cite":"37 F.4th 1170","y":2022,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/37/1170/","by":{"0":"22, 24, 25, 27, 28, 31, 39, 40","2":"3, 4, 5, 12"},"q":[{"src":"brief","b":0,"text":"rigid procedure, to ensure that any forfeiture order is correct before it becomes final.","cite":"37 F.4th at 1175"},{"src":"brief","b":0,"text":"Rule 32.2(b) envisions only one bite at the apple—unless Rules 35(a) or 36 permit a later, smaller bite after sentencing.","cite":"37 F.4th at 1177"},{"src":"brief","b":2,"text":"Dolan provides little direct guidance for the precise issue here.","cite":"37 F.4th 1170, 1176"},{"src":"brief","b":2,"text":"Rule 32.2(b) flips that script—it arms defendants with procedures to correct preliminary forfeiture orders before sentencing.","cite":"37 F.4th at 1178"}]},{"t":"case","label":"United States v. Marion","cite":"404 U.S. 307","y":1971,"id":"1971/70-19","sc":1,"by":{"0":"18"}},{"t":"case","label":"United States v. McIntosh","cite":"24 F.4th 857","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/24/857/","by":{"0":"7"}},{"t":"case","label":"United States v. McIntosh","cite":"2022 WL 274225","y":2022,"court":"2d. Cir. Jan. 31","by":{"0":"7"}},{"t":"case","label":"United States v. Mincey","cite":"800 F. Appx 714","y":2020,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20Appx/800/714/","by":{"0":"32"}},{"t":"case","label":"United States v. Montalvo-Murillo","cite":"495 U.S. 711","y":1990,"id":"1989/89-163","sc":1,"by":{"0":"38","1":"20, 37, 38","2":"8"},"q":[{"src":"argument","who":"Mr. Yurowitz","text":"Those cases involved either administrative rules and the concern of imposing mandatory conditions on bureaucratic agencies or rules designed to protect third parties, not before the court, such as the victims in Dolan and the public in Montalvo-Murillo."},{"src":"argument","who":"Mr. Guarnieri","text":"The -- the other case that I think is -- is directly on point here is Montalvo-Murillo, which is the case involving a provision of the Bail Reform Act that imposed on the magistrate, on the judicial officer, an obligation to hold a pretrial detention hearing within a specified time, and the Court said that even if a -- if the judicial officer violates that deadline, it doesn't mean that the defendant walks free."}]},{"t":"case","label":"United States v. Robinson","cite":"361 U.S. 220","y":1960,"id":"1959/16","sc":1,"by":{"0":"33"}},{"t":"case","label":"United States v. Shakur","cite":"691 F.3d 979","y":2012,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/691/979/","by":{"0":"20, 26, 30","2":"3, 9"}},{"t":"case","label":"United States v. Taylor","cite":"142 S. Ct. 2015","y":2022,"id":"2021/20-1459","sc":1,"by":{"0":"8","1":"11"}},{"t":"case","label":"United States v. Ursery","cite":"518 U.S. 267","y":1996,"id":"1995/95-345","sc":1,"by":{"0":"43"}},{"t":"case","label":"United States v. Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"by":{"0":"34"}},{"t":"case","label":"Univ. of Texas Sw. Med. Ctr. v. Nassar","cite":"570 U.S. 338","y":2013,"id":"2012/12-484","sc":1,"by":{"0":"20"}},{"t":"case","label":"Wilkins v. United States","cite":"598 U.S. 152","y":2023,"id":"2022/21-1164","sc":1,"by":{"0":"35","1":"19, 23"},"q":[{"src":"brief","b":1,"text":"‘may be raised at any time’ and courts have a duty to consider them sua sponte.","cite":"598 U.S. 152, 157"},{"src":"brief","b":1,"text":"‘Congress imbued a procedural bar with jurisdictional consequences.’","cite":"598 U.S. at 158"}]},{"t":"case","label":"Wilton v. Seven Falls Co.","cite":"515 U.S. 277","y":1995,"id":"1994/94-562","sc":1,"by":{"0":"20"}},{"t":"usc","label":"18 U.S.C. § 981","url":"https://www.law.cornell.edu/uscode/text/18/981","subs":["(a)(1)(C)"],"stext":{"head":"§981. Civil forfeiture","paras":[[0,"(a)(1) The following property is subject to forfeiture to the United States:"],[1,"(A) Any property, real or personal, involved in a transaction or attempted transaction in violation of section 1956, 1957 or 1960 of this title, or any property traceable to such property."],[1,"(B) Any property, real or personal, within the jurisdiction of the United States, constituting, derived from, or traceable to, any proceeds obtained directly or indirectly from an offense against a foreign nation, or any property used to facilitate such an offense, if the offense—"],[2,"(i) involves trafficking in nuclear, chemical, biological, or radiological weapons technology or material, or the manufacture, importation, sale, or distribution of a controlled substance (as that term is defined for purposes of the Controlled Substances Act), or any other conduct described in section 1956(c)(7)(B);"],[2,"(ii) would be punishable within the jurisdiction of the foreign nation by death or imprisonment for a term exceeding 1 year; and"],[2,"(iii) would be punishable under the laws of the United States by imprisonment for a term exceeding 1 year, if the act or activity constituting the offense had occurred within the jurisdiction of the United States."],[1,"(C) Any property, real or personal, which constitutes or is derived from proceeds traceable to a violation of section 215, 471, 472, 473, 474, 476, 477, 478, 479, 480, 481, 485, 486, 487, 488, 501, 502, 510, 542, 545, 656, 657, 670, 842, 844, 1005, 1006, 1007, 1014, 1028, 1029, 1030, 1032, or 1344 of this title or any offense constituting \"specified unlawful activity\" (as defined in section 1956(c)(7) of this title), or a conspiracy to commit such offense."],[1,"(D) Any property, real or personal, which represents or is traceable to the gross receipts obtained, directly or indirectly, from a violation of—"],[2,"(i) section 666(a)(1) (relating to Federal program fraud);"],[2,"(ii) section 1001 (relating to fraud and false statements);"],[2,"(iii) section 1031 (relating to major fraud against the United States);"],[2,"(iv) section 1032 (relating to concealment of assets from conservator or receiver of insured financial institution);"],[2,"(v) section 1341 (relating to mail fraud); or"],[2,"(vi) section 1343 (relating to wire fraud),"],[1,"if such violation relates to the sale of assets acquired or held by the the 1 Federal Deposit Insurance Corporation, as conservator or receiver for a financial institution, or any other conservator for a financial institution appointed by the Office of the Comptroller of the Currency or the National Credit Union Administration, as conservator or liquidating agent for a financial institution."],[1,"(E) With respect to an offense listed in subsection (a)(1)(D) committed for the purpose of executing or attempting to execute any scheme or artifice to defraud, or for obtaining money or property by means of false or fraudulent statements, pretenses, representations or promises, the gross receipts of such an offense shall include all property, real or personal, tangible or intangible, which thereby is obtained, directly or indirectly."],[1,"(F) Any property, real or personal, which represents or is traceable to the gross proceeds obtained, directly or indirectly, from a violation of—"],[2,"(i) section 511 (altering or removing motor vehicle identification numbers);"],[2,"(ii) section 553 (importing or exporting stolen motor vehicles);"],[2,"(iii) section 2119 (armed robbery of automobiles);"],[2,"(iv) section 2312 (transporting stolen motor vehicles in interstate commerce); or"],[2,"(v) section 2313 (possessing or selling a stolen motor vehicle that has moved in interstate commerce)."],[1,"(G) All assets, foreign or domestic—"],[2,"(i) of any individual, entity, or organization engaged in planning or perpetrating any any 1 Federal crime of terrorism (as defined in section 2332b(g)(5)) against the United States, citizens or residents of the United States, or their property, and all assets, foreign or domestic, affording any person a source of influence over any such entity or organization;"],[2,"(ii) acquired or maintained by any person with the intent and for the purpose of supporting, planning, conducting, or concealing any Federal crime of terrorism (as defined in section 2332b(g)(5) 2 against the United States, citizens or residents of the United States, or their property;"],[2,"(iii) derived from, involved in, or used or intended to be used to commit any Federal crime of terrorism (as defined in section 2332b(g)(5)) against the United States, citizens or residents of the United States, or their property; or"],[2,"(iv) of any individual, entity, or organization engaged in planning or perpetrating any act of international terrorism (as defined in section 2331) against any international organization (as defined in section 209 of the State Department Basic Authorities Act of 1956 (22 U.S.C. 4309(b)) or against any foreign Government.3 Where the property sought for forfeiture is located beyond the territorial boundaries of the United States, an act in furtherance of such planning or perpetration must have occurred within the jurisdiction of the United States."],[1,"(H) Any property, real or personal, involved in a violation or attempted violation, or which constitutes or is derived from proceeds traceable to a violation, of section 2339C of this title."],[1,"(I) Any property, real or personal, that is involved in a violation or attempted violation, or which constitutes or is derived from proceeds traceable to a prohibition imposed pursuant to section 104(a) of the North Korea Sanctions and Policy Enhancement Act of 2016."],[0,"(2) For purposes of paragraph (1), the term \"proceeds\" is defined as follows:"],[1,"(A) In cases involving illegal goods, illegal services, unlawful activities, and telemarketing and health care fraud schemes, the term \"proceeds\" means property of any kind obtained directly or indirectly, as the result of the commission of the offense giving rise to forfeiture, and any property traceable thereto, and is not limited to the net gain or profit realized from the offense."],[1,"(B) In cases involving lawful goods or lawful services that are sold or provided in an illegal manner, the term \"proceeds\" means the amount of money acquired through the illegal transactions resulting in the forfeiture, less the direct costs incurred in providing the goods or services. The claimant shall have the burden of proof with respect to the issue of direct costs. The direct costs shall not include any part of the overhead expenses of the entity providing the goods or services, or any part of the income taxes paid by the entity."],[1,"(C) In cases involving fraud in the process of obtaining a loan or extension of credit, the court shall allow the claimant a deduction from the forfeiture to the extent that the loan was repaid, or the debt was satisfied, without any financial loss to the victim."],[0,"(b)(1) Except as provided in section 985, any property subject to forfeiture to the United States under subsection (a) may be seized by the Attorney General and, in the case of property involved in a violation investigated by the Secretary of the Treasury or the United States Postal Service, the property may also be seized by the Secretary of the Treasury or the Postal Service, respectively."],[0,"(2) Seizures pursuant to this section shall be made pursuant to a warrant obtained in the same manner as provided for a search warrant under the Federal Rules of Criminal Procedure, except that a seizure may be made without a warrant if—"],[1,"(A) a complaint for forfeiture has been filed in the United States district court and the court issued an arrest warrant in rem pursuant to the Supplemental Rules for Certain Admiralty and Maritime Claims;"],[1,"(B) there is probable cause to believe that the property is subject to forfeiture and—"],[2,"(i) the seizure is made pursuant to a lawful arrest or search; or"],[2,"(ii) another exception to the Fourth Amendment warrant requirement would apply; or"],[1,"(C) the property was lawfully seized by a State or local law enforcement agency and transferred to a Federal agency."],[0,"(3) Notwithstanding the provisions of rule 41(a) 4 of the Federal Rules of Criminal Procedure, a seizure warrant may be issued pursuant to this subsection by a judicial officer in any district in which a forfeiture action against the property may be filed under section 1355(b) of title 28, and may be executed in any district in which the property is found, or transmitted to the central authority of any foreign state for service in accordance with any treaty or other international agreement. Any motion for the return of property seized under this section shall be filed in the district court in which the seizure warrant was issued or in the district court for the district in which the property was seized."],[0,"(4)(A) If any person is arrested or charged in a foreign country in connection with an offense that would give rise to the forfeiture of property in the United States under this section or under the Controlled Substances Act, the Attorney General may apply to any Federal judge or magistrate judge in the district in which the property is located for an ex parte order restraining the property subject to forfeiture for not more than 30 days, except that the time may be extended for good cause shown at a hearing conducted in the manner provided in rule 43(e) of the Federal Rules of Civil Procedure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/981?type=usc&year=mostrecent&link-type=html"},"by":{"0":"43","1":"5"},"q":[{"src":"brief","b":1,"text":"[a]ny property, real or personal, which constitutes or is derived from proceeds traceable to [the] violation.","cite":"18 U.S.C. 981(a)(1)(C)"}]},{"t":"usc","label":"18 U.S.C. § 982","url":"https://www.law.cornell.edu/uscode/text/18/982","subs":["(b)(1)"],"by":{"0":"40"}},{"t":"usc","label":"18 U.S.C. § 3663A","url":"https://www.law.cornell.edu/uscode/text/18/3663A","subs":["(c)","(a)(1)"],"stext":{"head":"§3663A. Mandatory restitution to victims of certain crimes","paras":[[0,"(a)(1) Notwithstanding any other provision of law, when sentencing a defendant convicted of an offense described in subsection (c), the court shall order, in addition to, or in the case of a misdemeanor, in addition to or in lieu of, any other penalty authorized by law, that the defendant make restitution to the victim of the offense or, if the victim is deceased, to the victim's estate."],[0,"(2) For the purposes of this section, the term \"victim\" means a person directly and proximately harmed as a result of the commission of an offense for which restitution may be ordered including, in the case of an offense that involves as an element a scheme, conspiracy, or pattern of criminal activity, any person directly harmed by the defendant's criminal conduct in the course of the scheme, conspiracy, or pattern. In the case of a victim who is under 18 years of age, incompetent, incapacitated, or deceased, the legal guardian of the victim or representative of the victim's estate, another family member, or any other person appointed as suitable by the court, may assume the victim's rights under this section, but in no event shall the defendant be named as such representative or guardian."],[0,"(3) The court shall also order, if agreed to by the parties in a plea agreement, restitution to persons other than the victim of the offense."],[0,"(4) Clarification.—In ordering restitution under this section, a court shall order the defendant to make restitution to a person who has assumed the victim's rights under paragraph (2) to reimburse that person's necessary and reasonable—"],[1,"(A) lost income, child care, transportation, and other expenses incurred during and directly related to participation in the investigation or prosecution of the offense or attendance at proceedings related to the offense;"],[1,"(B) lost income, transportation, and other expenses incurred that are directly related to transporting the victim for necessary medical and related professional services and devices relating to physical, psychiatric, and psychological care, including nonmedical care and treatment rendered in accordance with a method of healing recognized by the law of the place of treatment; and"],[1,"(C) lost income, transportation, and other expenses incurred that are directly related to transporting the victim to receive necessary physical and occupational therapy and rehabilitation."],[0,"(b) The order of restitution shall require that such defendant—"],[1,"(1) in the case of an offense resulting in damage to or loss or destruction of property of a victim of the offense—"],[2,"(A) return the property to the owner of the property or someone designated by the owner; or"],[2,"(B) if return of the property under subparagraph (A) is impossible, impracticable, or inadequate, pay an amount equal to—"],[3,"(i) the greater of—"],[4,"(I) the value of the property on the date of the damage, loss, or destruction; or"],[4,"(II) the value of the property on the date of sentencing, less"],[3,"(ii) the value (as of the date the property is returned) of any part of the property that is returned;"],[1,"(2) in the case of an offense resulting in bodily injury to a victim—"],[2,"(A) pay an amount equal to the cost of necessary medical and related professional services and devices relating to physical, psychiatric, and psychological care, including nonmedical care and treatment rendered in accordance with a method of healing recognized by the law of the place of treatment;"],[2,"(B) pay an amount equal to the cost of necessary physical and occupational therapy and rehabilitation; and"],[2,"(C) reimburse the victim for income lost by such victim as a result of such offense;"],[1,"(3) in the case of an offense resulting in bodily injury that results in the death of the victim, pay an amount equal to the cost of necessary funeral and related services; and"],[1,"(4) in any case, reimburse the victim for lost income and necessary child care, transportation, and other expenses incurred during participation in the investigation or prosecution of the offense or attendance at proceedings related to the offense."],[0,"(c)(1) This section shall apply in all sentencing proceedings for convictions of, or plea agreements relating to charges for, any offense—"],[1,"(A) that is—"],[2,"(i) a crime of violence, as defined in section 16;"],[2,"(ii) an offense against property under this title, or under section 416(a) of the Controlled Substances Act (21 U.S.C. 856(a)), including any offense committed by fraud or deceit;"],[2,"(iii) an offense described in section 3 of the Rodchenkov Anti-Doping Act of 2019;"],[2,"(iv) an offense described in section 1365 (relating to tampering with consumer products); or"],[2,"(v) an offense under section 670 (relating to theft of medical products); and"],[1,"(B) in which an identifiable victim or victims has suffered a physical injury or pecuniary loss."],[0,"(2) In the case of a plea agreement that does not result in a conviction for an offense described in paragraph (1), this section shall apply only if the plea specifically states that an offense listed under such paragraph gave rise to the plea agreement."],[0,"(3) This section shall not apply in the case of an offense described in paragraph (1)(A)(ii) or (iii) if the court finds, from facts on the record, that—"],[1,"(A) the number of identifiable victims is so large as to make restitution impracticable; or"],[1,"(B) determining complex issues of fact related to the cause or amount of the victim's losses would complicate or prolong the sentencing process to a degree that the need to provide restitution to any victim is outweighed by the burden on the sentencing process."],[0,"(d) An order of restitution under this section shall be issued and enforced in accordance with section 3664."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3663A?type=usc&year=mostrecent&link-type=html"},"by":{"0":"40","1":"19"},"q":[{"src":"brief","b":1,"text":"shall order * * * that the defendant make restitution to the victim of the offense.","cite":"18 U.S.C. 3663A(a)(1)"}]},{"t":"usc","label":"21 U.S.C. § 853","url":"https://www.law.cornell.edu/uscode/text/21/853","subs":["(i)","(a)","(g)","(c)","(e)(1)","(e)","(i)(1)","(l)","(n)","(n)(1)","(k)(1)"],"stext":{"head":"§853. Criminal forfeitures","paras":[[0,"(a) Property subject to criminal forfeiture"],[0,"Any person convicted of a violation of this subchapter or subchapter II punishable by imprisonment for more than one year shall forfeit to the United States, irrespective of any provision of State law—"],[1,"(1) any property constituting, or derived from, any proceeds the person obtained, directly or indirectly, as the result of such violation;"],[1,"(2) any of the person's property used, or intended to be used, in any manner or part, to commit, or to facilitate the commission of, such violation; and"],[1,"(3) in the case of a person convicted of engaging in a continuing criminal enterprise in violation of section 848 of this title, the person shall forfeit, in addition to any property described in paragraph (1) or (2), any of his interest in, claims against, and property or contractual rights affording a source of control over, the continuing criminal enterprise."],[0,"The court, in imposing sentence on such person, shall order, in addition to any other sentence imposed pursuant to this subchapter or subchapter II, that the person forfeit to the United States all property described in this subsection. In lieu of a fine otherwise authorized by this part, a defendant who derives profits or other proceeds from an offense may be fined not more than twice the gross profits or other proceeds."],[0,"(b) Meaning of term \"property\""],[0,"Property subject to criminal forfeiture under this section includes—"],[1,"(1) real property, including things growing on, affixed to, and found in land; and"],[1,"(2) tangible and intangible personal property, including rights, privileges, interests, claims, and securities."],[0,"(c) Third party transfers"],[0,"All right, title, and interest in property described in subsection (a) vests in the United States upon the commission of the act giving rise to forfeiture under this section. Any such property that is subsequently transferred to a person other than the defendant may be the subject of a special verdict of forfeiture and thereafter shall be ordered forfeited to the United States, unless the transferee establishes in a hearing pursuant to subsection (n) that he is a bona fide purchaser for value of such property who at the time of purchase was reasonably without cause to believe that the property was subject to forfeiture under this section."],[0,"(d) Rebuttable presumption"],[0,"There is a rebuttable presumption at trial that any property of a person convicted of a felony under this subchapter or subchapter II is subject to forfeiture under this section if the United States establishes by a preponderance of the evidence that—"],[1,"(1) such property was acquired by such person during the period of the violation of this subchapter or subchapter II or within a reasonable time after such period; and"],[1,"(2) there was no likely source for such property other than the violation of this subchapter or subchapter II."],[0,"(e) Protective orders"],[0,"(1) Upon application of the United States, the court may enter a restraining order or injunction, require the execution of a satisfactory performance bond, or take any other action to preserve the availability of property described in subsection (a) for forfeiture under this section—"],[1,"(A) upon the filing of an indictment or information charging a violation of this subchapter or subchapter II for which criminal forfeiture may be ordered under this section and alleging that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section; or"],[1,"(B) prior to the filing of such an indictment or information, if, after notice to persons appearing to have an interest in the property and opportunity for a hearing, the court determines that—"],[2,"(i) there is a substantial probability that the United States will prevail on the issue of forfeiture and that failure to enter the order will result in the property being destroyed, removed from the jurisdiction of the court, or otherwise made unavailable for forfeiture; and"],[2,"(ii) the need to preserve the availability of the property through the entry of the requested order outweighs the hardship on any party against whom the order is to be entered:"],[0,"Provided, however, That an order entered pursuant to subparagraph (B) shall be effective for not more than ninety days, unless extended by the court for good cause shown or unless an indictment or information described in subparagraph (A) has been filed."],[0,"(2) A temporary restraining order under this subsection may be entered upon application of the United States without notice or opportunity for a hearing when an information or indictment has not yet been filed with respect to the property, if the United States demonstrates that there is probable cause to believe that the property with respect to which the order is sought would, in the event of conviction, be subject to forfeiture under this section and that provision of notice will jeopardize the availability of the property for forfeiture. Such a temporary order shall expire not more than fourteen days after the date on which it is entered, unless extended for good cause shown or unless the party against whom it is entered consents to an extension for a longer period. A hearing requested concerning an order entered under this paragraph shall be held at the earliest possible time and prior to the expiration of the temporary order."],[0,"(3) The court may receive and consider, at a hearing held pursuant to this subsection, evidence and information that would be inadmissible under the Federal Rules of Evidence."],[0,"(4) Order to repatriate and deposit.—"],[1,"(A) In general.—Pursuant to its authority to enter a pretrial restraining order under this section, the court may order a defendant to repatriate any property that may be seized and forfeited, and to deposit that property pending trial in the registry of the court, or with the United States Marshals Service or the Secretary of the Treasury, in an interest-bearing account, if appropriate."],[1,"(B) Failure to comply.—Failure to comply with an order under this subsection, or an order to repatriate property under subsection (p), shall be punishable as a civil or criminal contempt of court, and may also result in an enhancement of the sentence of the defendant under the obstruction of justice provision of the Federal Sentencing Guidelines."],[0,"(f) Warrant of seizure"],[0,"The Government may request the issuance of a warrant authorizing the seizure of property subject to forfeiture under this section in the same manner as provided for a search warrant. If the court determines that there is probable cause to believe that the property to be seized would, in the event of conviction, be subject to forfeiture and that an order under subsection (e) may not be sufficient to assure the availability of the property for forfeiture, the court shall issue a warrant authorizing the seizure of such property."],[0,"(g) Execution"],[0,"Upon entry of an order of forfeiture under this section, the court shall authorize the Attorney General to seize all property ordered forfeited upon such terms and conditions as the court shall deem proper. Following entry of an order declaring the property forfeited, the court may, upon application of the United States, enter such appropriate restraining orders or injunctions, require the execution of satisfactory performance bonds, appoint receivers, conservators, appraisers, accountants, or trustees, or take any other action to protect the interest of the United States in the property ordered forfeited. Any income accruing to or derived from property ordered forfeited under this section may be used to offset ordinary and necessary expenses to the property which are required by law, or which are necessary to protect the interests of the United States or third parties."],[0,"(h) Disposition of property"],[0,"Following the seizure of property ordered forfeited under this section, the Attorney General shall direct the disposition of the property by sale or any other commercially feasible means, making due provision for the rights of any innocent persons. Any property right or interest not exercisable by, or transferable for value to, the United States shall expire and shall not revert to the defendant, nor shall the defendant or any person acting in concert with him or on his behalf be eligible to purchase forfeited property at any sale held by the United States. Upon application of a person, other than the defendant or a person acting in concert with him or on his behalf, the court may restrain or stay the sale or disposition of the property pending the conclusion of any appeal of the criminal case giving rise to the forfeiture, if the applicant demonstrates that proceeding with the sale or disposition of the property will result in irreparable injury, harm, or loss to him."],[0,"(i) Authority of the Attorney General"],[0,"With respect to property ordered forfeited under this section, the Attorney General is authorized to—"],[1,"(1) grant petitions for mitigation or remission of forfeiture, restore forfeited property to victims of a violation of this subchapter, or take any other action to protect the rights of innocent persons which is in the interest of justice and which is not inconsistent with the provisions of this section;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/853?type=usc&year=mostrecent&link-type=html"},"by":{"0":"40, 40, 24","1":"40, 40, 40, 40, 40, 40, 40, 40, 40, 40","2":"9, 21, 21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 2072","url":"https://www.law.cornell.edu/uscode/text/28/2072","by":{"0":"33"}},{"t":"usc","label":"28 U.S.C. § 2107","url":"https://www.law.cornell.edu/uscode/text/28/2107","subs":["(a)","(c)"],"by":{"0":"14, 14"}},{"t":"law","label":"Plain Writing Act, Pub. L. No. 111-274","url":"https://www.govinfo.gov/link/plaw/111/public/274","by":{"0":"18"}},{"t":"rule","label":"Fed. R. Crim. P. 2","url":"https://www.law.cornell.edu/rules/frcrmp/rule_2","by":{"0":"28"},"q":[{"src":"brief","b":0,"text":"are to be interpreted to provide for the just determination of every criminal proceeding, to secure simplicity in procedure and fairness in administration, and to eliminate unjustifiable delay and expense.","cite":"Fed. R. Crim. P. 2"}]},{"t":"rule","label":"Fed. R. Crim. P. 32.2","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32.2","subs":["(a)","(b)","(b)(1)","(b)(1)(A)","(b)(1)(B)","(b)(2)(A)","(b)(2)(B)","(b)(2)(C)","(b)(3)","(b)(4)","(b)(4)(A)","(b)(4)(B)","(b)(4)(C)","(b)(5)","(b)(5)(A)","(b)(5)(B)","(b)(6)","(b)(6)(A)","(b)(7)","(c)","(c)(1)","(c)(1)(A)","(c)(1)(B)","(c)(2)","(c)(3)","(d)","(e)","(e)(1)","(e)(2)","(e)(2)(A)","(b)(2)(C)(iii)","(e)(1)(A)"],"by":{"0":"3, 17, 20, 23, 26, 28, 16, 24, 29, 17, 23, 26, 17, 20, 23, 29, 17, 23, 29, 30, 31, 41, 2, 9, 10, 16, 17, 21, 23, 27, 29, 32, 35, 20, 21, 37, 20, 24, 11, 24, 24, 25, 17, 19, 22, 26, 20, 22, 27, 29, 5, 13, 17, 18, 23, 18, 23, 18, 20, 22, 42, 30, 25, 30, 18, 42, 20, 20, 18, 24, 29, 21, 18, 20, 21, 20, 18, 24, 29, 42, 30, 31, 25, 31, 32, 28","2":"11, 16, 4, 17, 12, 21, 4"},"q":[{"src":"brief","b":0,"text":"that resulted from arithmetical, technical, or other clear error.","cite":"Fed. R. Crim. P. 32.2"},{"src":"brief","b":2,"text":"the parties have no opportunity to advise the court of omissions or errors in the order before it becomes final as to the defendant.","cite":"Fed. R. Crim. P. 32.2"}]},{"t":"rule","label":"Fed. R. Crim. P. 35","url":"https://www.law.cornell.edu/rules/frcrmp/rule_35","subs":["(a)"],"by":{"0":"20, 26, 25, 32"}},{"t":"rule","label":"Fed. R. Crim. P. 36","url":"https://www.law.cornell.edu/rules/frcrmp/rule_36","by":{"0":"19, 20, 25, 26"}},{"t":"rule","label":"Fed. R. Crim. P. 45","url":"https://www.law.cornell.edu/rules/frcrmp/rule_45","subs":["(b)(2)"],"by":{"0":"26"}},{"t":"case","label":"Bank of Nova Scotia v. United States","cite":"487 U.S. 250","y":1988,"id":"1987/87-578","sc":1,"by":{"1":"35"}},{"t":"case","label":"Caplin & Drysdale, Chartered v. United States","cite":"491 U.S. 617","y":1989,"id":"1988/87-1729","sc":1,"by":{"1":"36"}},{"t":"case","label":"Honeycutt v. United States","cite":"581 U.S. 443","y":2017,"id":"2016/16-142","sc":1,"by":{"1":"5, 13, 36"}},{"t":"case","label":"Kaley v. United States","cite":"571 U.S. 320","y":2014,"id":"2013/12-464","sc":1,"by":{"1":"36, 37, 39, 40"},"q":[{"src":"brief","b":1,"text":"punish wrongdoing, deter future illegality, and ‘lessen the economic power’ of criminal enterprises.","cite":"571 U.S. 320, 323"}]},{"t":"case","label":"Murphy v. Smith","cite":"583 U.S. 220","y":2018,"id":"2017/16-1067","sc":1,"by":{"1":"39"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"an official’s crucial duties are better carried out late than never.","cite":"139 S. Ct. 954, 967"}]},{"t":"case","label":"Regions Hosp. v. Shalala","cite":"522 U.S. 448","y":1998,"id":"1997/96-1375","sc":1,"by":{"1":"21, 37","2":"8"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"by":{"1":"24"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"580 U.S. 26","y":2016,"url":"https://supreme.justia.com/cases/federal/us/580/26/","sc":1,"by":{"1":"24, 25"}},{"t":"case","label":"United States v. Bajakajian","cite":"524 U.S. 321","y":1998,"id":"1997/96-1487","sc":1,"by":{"1":"36"}},{"t":"case","label":"United States v. Blackman","cite":"746 F.3d 137","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/746/137/","by":{"1":"34, 41"},"q":[{"src":"brief","b":1,"text":"when the relevant prerequisites are satisfied.","cite":"746 F.3d 137, 143"},{"src":"brief","b":1,"text":"victim’s hope of getting paid may rest on the government’s superior ability to collect and liquidate a defendant’s assets","cite":"746 F.3d at 143"}]},{"t":"case","label":"United States v. Farias","cite":"836 F.3d 1315","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/836/1315/","by":{"1":"42"}},{"t":"case","label":"United States v. Hampton","cite":"732 F.3d 687","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/732/687/","by":{"1":"34"}},{"t":"case","label":"United States v. James Daniel Good Real Prop.","cite":"510 U.S. 43","y":1993,"id":"1993/92-1180","sc":1,"by":{"1":"21, 24, 41","2":"8, 9"},"q":[{"src":"brief","b":1,"text":"long recognized that ‘many statutory requisitions intended for the guide of officers in the conduct of business devolved upon them . . . do not limit their power or render its exercise in disregard of the requisitions ineffectual.’","cite":"510 U.S. 43, 63"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"`requisitions intended for the guide of offcers in the conduct of business devolved upon them [that] do not limit their power or render its exercise in disregard of the requisitions ineffectual.'","cite":"510 U. S., at 63"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"will not in the ordinary course impose their own coercive sanction","cite":"510 U. S., at 63"}]},{"t":"case","label":"United States v. Lee","cite":"77 F.4th 565","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/77/565/","by":{"1":"18, 22, 24, 42"}},{"t":"case","label":"United States v. Martin","cite":"662 F.3d 301","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/662/301/","by":{"1":"39"}},{"t":"case","label":"United States v. Monsanto","cite":"491 U.S. 600","y":1989,"id":"1988/88-454","sc":1,"by":{"1":"34"},"q":[{"src":"brief","b":1,"text":"could not have chosen stronger words to express its intent that forfeiture be mandatory in cases where the statute applied.","cite":"491 U.S. 600, 607"}]},{"t":"case","label":"United States v. Pelullo","cite":"178 F.3d 196","y":1999,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/178/196/","by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"conclusively determines all of the defendant’s interest in the forfeited property.","cite":"178 F.3d 196, 202"}]},{"t":"case","label":"United States v. Phillips","cite":"704 F.3d 754","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/704/754/","by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"which the district court retains discretion to reduce or eliminate, the district court has no discretion to reduce or eliminate mandatory criminal forfeiture.","cite":"704 F.3d 754, 769"}]},{"t":"case","label":"United States v. Spencer","cite":"848 F.3d 324","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/324/","by":{"1":"29"}},{"t":"case","label":"United States v. Zelaya-Rosales","cite":"707 F.3d 542","y":2013,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/707/542/","by":{"1":"29"}},{"t":"law","label":"Pub. L. No. 106-185","url":"https://www.govinfo.gov/link/plaw/106/public/185","by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 109-177","url":"https://www.govinfo.gov/link/plaw/109/public/177","by":{"1":"4"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1976","by":{"1":"4"}},{"t":"usc","label":"31 U.S.C. § 3729","url":"https://www.law.cornell.edu/uscode/text/31/3729","by":{"1":"24"}},{"t":"usc","label":"31 U.S.C. § 3730","url":"https://www.law.cornell.edu/uscode/text/31/3730","subs":["(b)(2)"],"by":{"1":"24"},"q":[{"src":"brief","b":1,"text":"shall remain under seal for at least 60 days,","cite":"31 U.S.C. 3730(b)(2)"}]},{"t":"usc","label":"18 U.S.C. § 1951","url":"https://www.law.cornell.edu/uscode/text/18/1951","by":{"1":"2, 5, 7"}},{"t":"law","label":"Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"1":"10, 18"}},{"t":"usc","label":"28 U.S.C. § 2071","url":"https://www.law.cornell.edu/uscode/text/28/2071","by":{"1":"23"}},{"t":"usc","label":"18 U.S.C. § 2","url":"https://www.law.cornell.edu/uscode/text/18/2","by":{"1":"2, 7"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"by":{"1":"2, 7"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(2)","(c)","(c)(1)"],"by":{"1":"7, 2, 3, 8, 13, 2, 7"}},{"t":"usc","label":"18 U.S.C. § 1956","url":"https://www.law.cornell.edu/uscode/text/18/1956","subs":["(c)(7)"],"by":{"1":"5"}},{"t":"usc","label":"18 U.S.C. § 1961","url":"https://www.law.cornell.edu/uscode/text/18/1961","subs":["(1)"],"by":{"1":"5"}},{"t":"usc","label":"18 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/18/3231","by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"original jurisdiction * * * of all offenses against the laws of the United States.","cite":"18 U.S.C. 3231"}]},{"t":"usc","label":"18 U.S.C. § 3554","url":"https://www.law.cornell.edu/uscode/text/18/3554","stext":{"head":"§3554. Order of criminal forfeiture","paras":[[0,"The court, in imposing a sentence on a defendant who has been found guilty of an offense described in section 1962 of this title or in title II or III of the Comprehensive Drug Abuse Prevention and Control Act of 1970 shall order, in addition to the sentence that is imposed pursuant to the provisions of section 3551, that the defendant forfeit property to the United States in accordance with the provisions of section 1963 of this title or section 413 of the Comprehensive Drug Abuse and Control Act of 1970."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3554?type=usc&year=mostrecent&link-type=html"},"by":{"1":"19"},"q":[{"src":"brief","b":1,"text":"[t]he procedures in section 413 of the Controlled Substances Act (21 U.S.C. 853).","cite":"18 U.S.C. 3554"},{"src":"brief","b":1,"text":"shall order, in addition to the sentence that is imposed pursuant to the provisions of [18 U.S.C.] 3551, that the defendant forfeit property to the United States in accordance with * * * [21 U.S.C. 853].","cite":"18 U.S.C. 3554"}]},{"t":"usc","label":"18 U.S.C. § 3556","url":"https://www.law.cornell.edu/uscode/text/18/3556","by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 3571","url":"https://www.law.cornell.edu/uscode/text/18/3571","by":{"1":"35"}},{"t":"usc","label":"18 U.S.C. § 3664","url":"https://www.law.cornell.edu/uscode/text/18/3664","subs":["(d)(5)"],"stext":{"head":"§3664. Procedure for issuance and enforcement of order of restitution","paras":[[0,"(a) For orders of restitution under this title, the court shall order the probation officer to obtain and include in its presentence report, or in a separate report, as the court may direct, information sufficient for the court to exercise its discretion in fashioning a restitution order. The report shall include, to the extent practicable, a complete accounting of the losses to each victim, any restitution owed pursuant to a plea agreement, and information relating to the economic circumstances of each defendant. If the number or identity of victims cannot be reasonably ascertained, or other circumstances exist that make this requirement clearly impracticable, the probation officer shall so inform the court."],[0,"(b) The court shall disclose to both the defendant and the attorney for the Government all portions of the presentence or other report pertaining to the matters described in subsection (a) of this section."],[0,"(c) The provisions of this chapter, chapter 227, and Rule 32(c) of the Federal Rules of Criminal Procedure shall be the only rules applicable to proceedings under this section."],[0,"(d)(1) Upon the request of the probation officer, but not later than 60 days prior to the date initially set for sentencing, the attorney for the Government, after consulting, to the extent practicable, with all identified victims, shall promptly provide the probation officer with a listing of the amounts subject to restitution."],[0,"(2) The probation officer shall, prior to submitting the presentence report under subsection (a), to the extent practicable—"],[1,"(A) provide notice to all identified victims of—"],[2,"(i) the offense or offenses of which the defendant was convicted;"],[2,"(ii) the amounts subject to restitution submitted to the probation officer;"],[2,"(iii) the opportunity of the victim to submit information to the probation officer concerning the amount of the victim's losses;"],[2,"(iv) the scheduled date, time, and place of the sentencing hearing;"],[2,"(v) the availability of a lien in favor of the victim pursuant to subsection (m)(1)(B); and"],[2,"(vi) the opportunity of the victim to file with the probation officer a separate affidavit relating to the amount of the victim's losses subject to restitution; and"],[1,"(B) provide the victim with an affidavit form to submit pursuant to subparagraph (A)(vi)."],[0,"(3) Each defendant shall prepare and file with the probation officer an affidavit fully describing the financial resources of the defendant, including a complete listing of all assets owned or controlled by the defendant as of the date on which the defendant was arrested, the financial needs and earning ability of the defendant and the defendant's dependents, and such other information that the court requires relating to such other factors as the court deems appropriate."],[0,"(4) After reviewing the report of the probation officer, the court may require additional documentation or hear testimony. The privacy of any records filed, or testimony heard, pursuant to this section shall be maintained to the greatest extent possible, and such records may be filed or testimony heard in camera."],[0,"(5) If the victim's losses are not ascertainable by the date that is 10 days prior to sentencing, the attorney for the Government or the probation officer shall so inform the court, and the court shall set a date for the final determination of the victim's losses, not to exceed 90 days after sentencing. If the victim subsequently discovers further losses, the victim shall have 60 days after discovery of those losses in which to petition the court for an amended restitution order. Such order may be granted only upon a showing of good cause for the failure to include such losses in the initial claim for restitutionary relief."],[0,"(6) The court may refer any issue arising in connection with a proposed order of restitution to a magistrate judge or special master for proposed findings of fact and recommendations as to disposition, subject to a de novo determination of the issue by the court."],[0,"(e) Any dispute as to the proper amount or type of restitution shall be resolved by the court by the preponderance of the evidence. The burden of demonstrating the amount of the loss sustained by a victim as a result of the offense shall be on the attorney for the Government. The burden of demonstrating the financial resources of the defendant and the financial needs of the defendant's dependents, shall be on the defendant. The burden of demonstrating such other matters as the court deems appropriate shall be upon the party designated by the court as justice requires."],[0,"(f)(1)(A) In each order of restitution, the court shall order restitution to each victim in the full amount of each victim's losses as determined by the court and without consideration of the economic circumstances of the defendant."],[0,"(B) In no case shall the fact that a victim has received or is entitled to receive compensation with respect to a loss from insurance or any other source be considered in determining the amount of restitution."],[0,"(2) Upon determination of the amount of restitution owed to each victim, the court shall, pursuant to section 3572, specify in the restitution order the manner in which, and the schedule according to which, the restitution is to be paid, in consideration of—"],[1,"(A) the financial resources and other assets of the defendant, including whether any of these assets are jointly controlled;"],[1,"(B) projected earnings and other income of the defendant; and"],[1,"(C) any financial obligations of the defendant; including obligations to dependents."],[0,"(3)(A) A restitution order may direct the defendant to make a single, lump-sum payment, partial payments at specified intervals, in-kind payments, or a combination of payments at specified intervals and in-kind payments."],[0,"(B) A restitution order may direct the defendant to make nominal periodic payments if the court finds from facts on the record that the economic circumstances of the defendant do not allow the payment of any amount of a restitution order, and do not allow for the payment of the full amount of a restitution order in the foreseeable future under any reasonable schedule of payments."],[0,"(4) An in-kind payment described in paragraph (3) may be in the form of—"],[1,"(A) return of property;"],[1,"(B) replacement of property; or"],[1,"(C) if the victim agrees, services rendered to the victim or a person or organization other than the victim."],[0,"(g)(1) No victim shall be required to participate in any phase of a restitution order."],[0,"(2) A victim may at any time assign the victim's interest in restitution payments to the Crime Victims Fund in the Treasury without in any way impairing the obligation of the defendant to make such payments."],[0,"(h) If the court finds that more than 1 defendant has contributed to the loss of a victim, the court may make each defendant liable for payment of the full amount of restitution or may apportion liability among the defendants to reflect the level of contribution to the victim's loss and economic circumstances of each defendant."],[0,"(i) If the court finds that more than 1 victim has sustained a loss requiring restitution by a defendant, the court may provide for a different payment schedule for each victim based on the type and amount of each victim's loss and accounting for the economic circumstances of each victim. In any case in which the United States is a victim, the court shall ensure that all other victims receive full restitution before the United States receives any restitution."],[0,"(j)(1) If a victim has received compensation from insurance or any other source with respect to a loss, the court shall order that restitution be paid to the person who provided or is obligated to provide the compensation, but the restitution order shall provide that all restitution of victims required by the order be paid to the victims before any restitution is paid to such a provider of compensation."],[0,"(2) Any amount paid to a victim under an order of restitution shall be reduced by any amount later recovered as compensatory damages for the same loss by the victim in—"],[1,"(A) any Federal civil proceeding; and"],[1,"(B) any State civil proceeding, to the extent provided by the law of the State."],[0,"(k) A restitution order shall provide that the defendant shall notify the court and the Attorney General of any material change in the defendant's economic circumstances that might affect the defendant's ability to pay restitution. The court may also accept notification of a material change in the defendant's economic circumstances from the United States or from the victim. The Attorney General shall certify to the court that the victim or victims owed restitution by the defendant have been notified of the change in circumstances. Upon receipt of the notification, the court may, on its own motion, or the motion of any party, including the victim, adjust the payment schedule, or require immediate payment in full, as the interests of justice require."],[0,"(l) A conviction of a defendant for an offense involving the act giving rise to an order of restitution shall estop the defendant from denying the essential allegations of that offense in any subsequent Federal civil proceeding or State civil proceeding, to the extent consistent with State law, brought by the victim."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3664?type=usc&year=mostrecent&link-type=html"},"by":{"1":"11, 19","2":"4"},"q":[{"src":"brief","b":1,"text":"set a date for the final determination of the victim’s losses, not to exceed 90 days after sentencing.","cite":"18 U.S.C. 3664(d)(5)"},{"src":"opinion","who":"Opinion of the Court (Justice Sotomayor)","text":"[i]f the victim's losses are not ascertainable by the date that is 10 days prior to sentencing, . . . the court shall set a date for the fnal determination of the victim's losses, not to exceed 90 days after sentencing.","cite":"18 U. S. C. § 3664(d)(5)"}]},{"t":"usc","label":"18 U.S.C. § 3771","url":"https://www.law.cornell.edu/uscode/text/18/3771","by":{"1":"43"}},{"t":"usc","label":"28 U.S.C. § 524","url":"https://www.law.cornell.edu/uscode/text/28/524","subs":["(c)(1)","(c)(1)(E)(i)"],"by":{"1":"40, 40"}},{"t":"usc","label":"28 U.S.C. § 2461","url":"https://www.law.cornell.edu/uscode/text/28/2461","subs":["(c)"],"stext":{"head":"§2461. Mode of recovery","paras":[[0,"(a) Whenever a civil fine, penalty or pecuniary forfeiture is prescribed for the violation of an Act of Congress without specifying the mode of recovery or enforcement thereof, it may be recovered in a civil action."],[0,"(b) Unless otherwise provided by Act of Congress, whenever a forfeiture of property is prescribed as a penalty for violation of an Act of Congress and the seizure takes place on the high seas or on navigable waters within the admiralty and maritime jurisdiction of the United States, such forfeiture may be enforced by libel in admiralty but in cases of seizures on land the forfeiture may be enforced by a proceeding by libel which shall conform as near as may be to proceedings in admiralty."],[0,"(c) If a person is charged in a criminal case with a violation of an Act of Congress for which the civil or criminal forfeiture of property is authorized, the Government may include notice of the forfeiture in the indictment or information pursuant to the Federal Rules of Criminal Procedure. If the defendant is convicted of the offense giving rise to the forfeiture, the court shall order the forfeiture of the property as part of the sentence in the criminal case pursuant to to 1 the Federal Rules of Criminal Procedure and section 3554 of title 18, United States Code. The procedures in section 413 of the Controlled Substances Act (21 U.S.C. 853) apply to all stages of a criminal forfeiture proceeding, except that subsection (d) of such section applies only in cases in which the defendant is convicted of a violation of such Act."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2461?type=usc&year=mostrecent&link-type=html"},"by":{"1":"3, 34, 40","2":"16, 18"},"q":[{"src":"brief","b":1,"text":"may include no- tice of the forfeiture in the indictment or information pursuant to the Federal Rules of Criminal Procedure.","cite":"28 U.S.C. 2461(c)"},{"src":"brief","b":1,"text":"pursuant to * * * the Federal Rules of Criminal Procedure,","cite":"28 U.S.C. 2461(c)"},{"src":"brief","b":2,"text":"the Government may include notice of the forfeiture in the indictment or information pursuant to the Federal Rules of Criminal Procedure.","cite":"28 U.S.C. § 2461(c)"}]},{"t":"reg","label":"28 C.F.R. § 9.8","url":"https://www.ecfr.gov/current/title-28/section-9.8","by":{"1":"40"}},{"t":"case","label":"Bd. of Regents of State Coll. v. Roth","cite":"408 U.S. 564","y":1972,"id":"1971/71-162","sc":1,"by":{"2":"9"}},{"t":"case","label":"Botany Worsted Mills v. United States","cite":"278 U.S. 282","y":1929,"id":"scdb/1928-021","sc":1,"by":{"2":"13"}},{"t":"case","label":"Cont’l Cas. Co. v. United States","cite":"314 U.S. 527","y":1942,"id":"scdb/1941-033","sc":1,"by":{"2":"13"}},{"t":"case","label":"EEOC v. Waffle House, Inc.","cite":"534 U.S. 279","y":2002,"id":"2001/99-1823","sc":1,"by":{"2":"22"},"q":[{"src":"brief","b":2,"text":"what’s good for the goose is good for the gander,","cite":"534 U.S. 279, 314"}]},{"t":"case","label":"Hillman v. Maretta","cite":"569 U.S. 483","y":2013,"id":"2012/11-1221","sc":1,"by":{"2":"13"},"q":[{"src":"brief","b":2,"text":"explicitly enumerates certain exceptions to a general prohibition, additional exceptions are not to be implied.","cite":"569 U.S. 483, 496"}]},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"by":{"2":"9"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"by":{"2":"8"}},{"t":"case","label":"Southwest Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"id":"2021/21-309","sc":1,"by":{"2":"18"}},{"t":"case","label":"United States v. Lovasco","cite":"431 U.S. 783","y":1977,"id":"1976/75-1844","sc":1,"by":{"2":"11"}},{"t":"case","label":"United States v. Pagan","cite":"33 F.3d 125","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/33/125/","by":{"2":"15"}},{"t":"case","label":"United States v. Swartz Family Trust","cite":"67 F.4th 505","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/67/505/","by":{"2":"21"}}]};